sys_script_include.script:
function WaitForWorker(strProgressSysId,nSleepForSeconds,nTimeoutSeconds)
{
	nSleepForSeconds = GetIntegerValue(nSleepForSeconds);
	if (nSleepForSeconds == 0)
	{
		nSleepForSeconds = 1;
	} 
	nTimeoutSeconds = GetIntegerValue(nTimeoutSeconds);

	var grProgress = GetRecord('sys_progress_worker',strProgressSysId);
	if (grProgress == false)
	{
		return false;
	}
	var stopwatch = new StopWatch();
	stopwatch.Start();

	var bProgress = true;
	while (bProgress == true)
	{
		if (nTimeoutSeconds > 0)
		{
			if (stopwatch.GetSeconds() > nTimeoutSeconds)
			{
				return false;	
			}
		}
		if (grProgress.get(strProgressSysId))
		{
			var strState = GetStringValue(grProgress.state);  
			if (strState != 'starting' && strState != 'running')
			{
				return true;
			}
			else
			{
				Sleep(nSleepForSeconds);
			}
		}
		else
		{
			return false;
		}
	}
	return false;
}
